try {
    paso('Restaurando diseños de cotización...');
    paso('');

    // 1. Logos: sólo se escriben si la empresa existe en esta base.
    $dirLogos = __DIR__ . '/storage/logos';
    foreach ($logos as $empresaId => $b64) {
        $existe = (int) DB::valor('SELECT COUNT(*) FROM empresas WHERE id = :id', [':id' => $empresaId]);
        if (!$existe) {
            paso("[--] empresa_id $empresaId no existe aquí, se omite su logo");
            continue;
        }
        $destino = "$dirLogos/empresa-$empresaId.jpg";
        file_put_contents($destino, base64_decode($b64));
        paso("[OK] logo escrito: storage/logos/empresa-$empresaId.jpg");
    }

    paso('');

    // 2. Filas de cotizacion_config: upsert por empresa_id.
    $aplicadas = 0;
    $omitidas = 0;
    foreach ($filas as $fila) {
        $empresaId = $fila['empresa_id'];
        $existe = (int) DB::valor('SELECT COUNT(*) FROM empresas WHERE id = :id', [':id' => $empresaId]);
        if (!$existe) {
            paso("[--] empresa_id $empresaId no existe aquí, se omite su diseño");
            $omitidas++;
            continue;
        }

        $columnas = array_keys($fila);
        $actualizables = array_diff($columnas, ['empresa_id']);
        // Prepares nativos no permiten repetir un mismo :marcador en la misma
        // consulta, así que el UPDATE usa nombres distintos (sufijo _u).
        $sets = implode(', ', array_map(fn($c) => "$c = :{$c}_u", $actualizables));
        $campos = implode(', ', $columnas);
        $marcadores = implode(', ', array_map(fn($c) => ":$c", $columnas));

        $params = [];
        foreach ($columnas as $c) { $params[":$c"] = $fila[$c]; }
        foreach ($actualizables as $c) { $params[":{$c}_u"] = $fila[$c]; }

        DB::query(
            "INSERT INTO cotizacion_config ($campos) VALUES ($marcadores)
             ON DUPLICATE KEY UPDATE $sets",
            $params
        );
        paso("[OK] diseño aplicado: empresa_id $empresaId");
        $aplicadas++;
    }

    paso('');
    paso("Listo: $aplicadas diseño(s) aplicado(s), $omitidas omitido(s) por no existir la empresa.");

} catch (Throwable $e) {
    http_response_code(500);
    paso('[ERROR] ' . $e->getMessage());
}